 zbritje = Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) - (Convert.ToDouble(GetCurrentColumnValue("TOTALI")) - totalipatvsh - Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL")));
